    if (!decoded.data) { setNotice(decoded.error); return; }
    const data = decoded.data;
    leaveOr(() => { setTournament(data.tournament); setPendingSnapshot(data.snapshot); setPlaying(false); setNotice('Tournament loaded.'); setConfirm(null); });
  }
  const player = tournament && match && match.results.length < 2 ? tournament.names[match.players[match.results.length] ?? 0] : null;
  return <>
    <h2 ref={heading} tabIndex={-1}>Tournament</h2>
    {!tournament && <section className="tournament-section">
      <div className="tournament-fields"><label htmlFor="players">Players</label><select className="control" id="players" value={count} onChange={(e) => setCount(Number(e.target.value))}><option value={4}>4</option><option value={8}>8</option></select></div>
      <div className="tournament-names">{drafts.slice(0, count).map((name, i) => <label key={i}>Player {i + 1}<input className="control" value={name} onChange={(e) => setDrafts(drafts.map((v, j) => i === j ? e.target.value : v))} /></label>)}</div>
      <button className="control" onClick={startTournament}>Start tournament</button>
      <h3>Past tournaments</h3>
      {unavailable && <p>Progress won't be saved on this device.</p>}
      {past.length === 0 ? <p>No past tournaments.</p> : <ul>{past.map((t, i) => { const last = t.matches.at(-1); const won = last && winner(last); return <li key={i}><button className="control" onClick={() => { setTournament(t); setNotice('Tournament loaded.'); }}>Champion: {won === null || won === undefined ? '' : t.names[won]}</button></li>; })}</ul>}
      <button className="control" onClick={back}>Back to game</button>
    </section>}
    {tournament && <section className="tournament-section">
      {champion !== null && champion !== undefined ? <><p>Champion: {tournament.names[champion]}</p><button className="control" onClick={back}>Back to game</button><button className="control" onClick={() => { setTournament(null); setNotice(''); }}>Tournament setup</button></> : <>
        <p>Round: {roundName(tournament.names.length, tournament.matches.length - 1)}</p>
        {player && <p>Now playing: {player}</p>}
        {!playing && match && match.results.length < 2 && <button className="control" onClick={startTurn}>Start turn</button>}
        {!playing && match?.results.length === 1 && <button className="control" onClick={startTurn}>Next turn</button>}
        {!playing && match?.results.length === 2 && <button className="control" onClick={() => { setTournament(makeMatch(tournament)); setNotice('Next match.'); }}>Next match</button>}
        <button className="control" onClick={() => leaveOr(back)}>Leave tournament</button>
      </>}
      <Bracket tournament={tournament} />
    </section>}
    {playing && <><GameStatus game={game.session.game} best={undefined} celebration={game.session.celebration} /><p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p><Board key={game.session.generation} game={game.session.game} activate={game.activate} ref={board} /></>}
    <div className="game-result"><p role="status" aria-live="polite" aria-atomic="true">{playing ? game.session.feedback || notice : notice}</p></div>
    <section className="tournament-section"><label htmlFor="tournament-json">Tournament JSON</label><textarea id="tournament-json" className="control tournament-json" value={json} onChange={(e) => setJson(e.target.value)} />
      <div className="tournament-actions"><button className="control" onClick={() => { setJson(encodeExchange({ tournament, snapshot: playing ? game.exportGame() : pendingSnapshot })); setNotice('Tournament exported.'); }}>Export tournament</button><button className="control" onClick={load}>Load tournament</button></div>
    </section>
    {confirm && <LeaveDialog keep={() => setConfirm(null)} leave={confirm} />}
  </>;
}
